// function that streams wsdl content to client if requested
int streamWSDLFile(struct soap *sp)
{
    FILE *fd;
    // size_t r;
    //	const char *s = appSettings::wsdlPath;
    fd = fopen(ServiceSettings::wsdlPath.c_str(), "rb"); // open WSDL file to copy
    if (!fd)
    {
        LOG(ERROR) << "WSDL file " << ServiceSettings::wsdlPath << " not found";
        return soap_send_empty_response(sp, 404); // return HTTP not found error
    }
    //   soap->http_content

    sp->http_content = "text/xml; charset=utf-8"; // HTTP header with text/xml content
    soap_response(sp, SOAP_FILE);
    for (;;)
    {
        size_t r = fread(sp->tmpbuf, 1, sizeof(sp->tmpbuf), fd);
        if (!r)
            break;
        if (soap_send_raw(sp, sp->tmpbuf, r))
            break; // can't send, but little we can do about that
    }
    fclose(fd);
    return soap_end_send(sp);
}

// Records the SOAP fault; serve() sends it once the operation returns SOAP_FAULT.
// (It used to call soap_send_fault() here as well, so every error produced two SOAP envelopes.)
int sendError(struct soap *sp)
{
    LOG(INFO)<<"Unable to serve request, returning error description";
    return soap_receiver_fault(sp,ErrorResponse::getFaultString().c_str(),ErrorResponse::getFaultDetail().c_str());
}

int sendError(struct soap *sp, std::string message)
{
    LOG(INFO)<<"Unable to serve request, returning error description";
    return soap_receiver_fault(sp,ErrorResponse::getFaultString().c_str(),message.c_str());
}
